#!/usr/bin/env bash
set -euo pipefail
BOOK_ROOT=$(git rev-parse --show-toplevel)
TUSIM_ROOT=/home/zxy/Workplace/projects/tusim
PIN=e918c80b6fce833cd1fcae97730fa841c2176f25
RUN_ID=${CH21_RUN_ID:-20260818-ch21-postreview-v1}
[[ $RUN_ID =~ ^20260818-ch21-postreview-v[1-9][0-9]*$ ]]
RUNS=$(realpath "$BOOK_ROOT/experiments/runs")
RUN_DIR="$RUNS/$RUN_ID"
[[ $(dirname "$RUN_DIR") == "$RUNS" ]]
INPUT_COMMIT=$(git rev-parse HEAD);BOOK_BRANCH=$(git branch --show-current)
WORK_PARENT=$(mktemp -d /tmp/ch21-postreview-XXXXXX);WORK="$WORK_PARENT/src";TRANSCRIPT="$RUN_DIR/transcript.log";AFTER_DONE=0
SOURCE_IGNORED_BEFORE=$(git -C "$TUSIM_ROOT" status --porcelain=v1 --ignored|sha256sum|cut -d' ' -f1)
INPUTS=(edition.yaml notes/chapter-21-framing-and-evidence-plan.md notes/chapter-21-framing-review-dispositions.md notes/chapter-21-source-and-claim-ledger.md notes/chapter-21-limitation-register.md notes/chapter-21-worked-decision-schema.json notes/chapter-21-metric-fidelity-register.json notes/chapter-21-predraft-audit-report.md notes/chapter-21-skeptical-predraft-review-dispositions.md references/ch21-sweep-method-primary-sources.md references/ch21-primary-source-verification-ledger.json experiments/ch21_source_audit.py experiments/ch21_boundary_audit.py experiments/ch21_sweep_probe.c experiments/ch21_formula_probe.py experiments/run_ch21_sweep_evidence_audit.sh experiments/ch21_predraft_validate.py)
BASE=(archive-members.log aspect-raw.log aspect-rows.csv body-validation-normal.log body-validation-optimized.log boundary-audit.log boundary-mutation.log build.log commands.txt decision-schema-check.log environment.txt failure-early.log failure-early-summary.log formula-mutation.log formula-results.json formula.log input-hashes.txt input_commit inventory.json manifest-hierarchy-mutations.log metric-register.json probe-O0-dynamic.log probe-O0.log probe-O0.stderr.log probe-O2-dynamic.log probe-O2.log probe-O2.stderr.log probe-route-mutation.log relation-mutation.log report-role-mutation.log sensitivity-rows.csv source-audit-hash-mutation.log source-audit-restored.log source-audit.log source-state-expected.txt source_pin status-mutation.log transcript.log validator-assert-mutation-normal.log validator-assert-mutation-optimized.log validator-input-mutation-normal.log validator-input-mutation-optimized.log)
source_state(){ local label=$1 head branch status ignored;head=$(git -C "$TUSIM_ROOT" rev-parse HEAD);branch=$(git -C "$TUSIM_ROOT" symbolic-ref -q --short HEAD||true);status=$(git -C "$TUSIM_ROOT" status --porcelain=v1);ignored=$(git -C "$TUSIM_ROOT" status --porcelain=v1 --ignored|sha256sum|cut -d' ' -f1);printf 'SOURCE_STATE %s head=%s detached=%s dirty_entries=%s ignored_hash=%s\n' "$label" "$head" "$([[ -z $branch ]]&&echo 1||echo 0)" "$([[ -z $status ]]&&echo 0||printf '%s\n' "$status"|wc -l)" "$ignored";[[ $head == "$PIN" && -z $branch && -z $status && $ignored == "$SOURCE_IGNORED_BEFORE" ]];}
cleanup(){ local rc=$?;if [[ $AFTER_DONE -eq 0 ]];then source_state after||rc=1;fi;rm -rf "$WORK_PARENT";exit "$rc";};trap cleanup EXIT
[[ $BOOK_BRANCH == main ]];[[ -z $(git status --porcelain=v1) ]];[[ ! -e $RUN_DIR ]];source_state preflight >/dev/null
mkdir -p "$RUN_DIR/inputs" "$WORK";printf '%s\n' "$INPUT_COMMIT" >"$RUN_DIR/input_commit";printf '%s\n' "$PIN" >"$RUN_DIR/source_pin"
for rel in "${INPUTS[@]}";do mkdir -p "$RUN_DIR/inputs/$(dirname "$rel")";cp "$BOOK_ROOT/$rel" "$RUN_DIR/inputs/$rel";done
(cd "$BOOK_ROOT"&&sha256sum "${INPUTS[@]}") >"$RUN_DIR/input-hashes.txt"
source_state after >"$RUN_DIR/source-state-expected.txt"
set +e;(set -euo pipefail;source_state before;printf 'INJECT early-inventory-failure\n';false;printf 'SURVIVED\n') >"$RUN_DIR/failure-early.log" 2>&1;rc=$?;set -e;source_state after >>"$RUN_DIR/failure-early.log";[[ $rc -ne 0 ]];! grep -Fq SURVIVED "$RUN_DIR/failure-early.log";printf 'FAILURE_EARLY rejected_rc=%d source_after_unique=1\n' "$rc" >"$RUN_DIR/failure-early-summary.log"
git -C "$TUSIM_ROOT" archive --format=tar --output="$WORK_PARENT/tusim.tar" "$PIN";tar -xf "$WORK_PARENT/tusim.tar" -C "$WORK"
body(){
 source_state before;printf 'BOOK_STATE head=%s branch=%s clean=1\n' "$INPUT_COMMIT" "$BOOK_BRANCH"
 printf 'TOOLCHAIN host=%s cc=%s make=%s python=%s locale=C\n' "$(uname -m)" "$(cc --version|head -1)" "$(make --version|head -1)" "$(python3 --version)"
 printf '%s\n' "git -C $TUSIM_ROOT archive --format=tar $PIN" "make -C <archive> -j2 libtucmodel.a" "cc -O0/-O2 -std=c11 -I<archive> ch21_sweep_probe.c <archive>/libtucmodel.a -lm" "python3 <archive>/scripts/sweep_aspect_ratio.py" "python3 experiments/ch21_formula_probe.py <output-dir>" "python3 experiments/ch21_predraft_validate.py --body|--outer|--postseal" >"$RUN_DIR/commands.txt"
 printf 'host=%s\ncc=%s\nmake=%s\npython=%s\nlocale=C\nsource_pin=%s\n' "$(uname -m)" "$(cc --version|head -1)" "$(make --version|head -1)" "$(python3 --version)" "$PIN" >"$RUN_DIR/environment.txt"
 python3 experiments/ch21_source_audit.py "$WORK" "$PIN" "$RUN_DIR/inventory.json"|tee "$RUN_DIR/source-audit.log"
 cp "$WORK/tu_cmodel/tu_core.c" "$WORK_PARENT/core.orig";printf '\n' >>"$WORK/tu_cmodel/tu_core.c";set +e;python3 experiments/ch21_source_audit.py "$WORK" "$PIN" >"$RUN_DIR/source-audit-hash-mutation.log" 2>&1;hrc=$?;set -e;[[ $hrc -ne 0 ]];cp "$WORK_PARENT/core.orig" "$WORK/tu_cmodel/tu_core.c";python3 experiments/ch21_source_audit.py "$WORK" "$PIN" >"$RUN_DIR/source-audit-restored.log";printf 'SOURCE_HASH_MUTATION rejected=1 restored=1\n'
 local rel="$WORK_PARENT/relation";mkdir "$rel";tar -xf "$WORK_PARENT/tusim.tar" -C "$rel";python3 -c 'from pathlib import Path;import sys;p=Path(sys.argv[1]);s=p.read_text();a="test-bench: tests/test_benchmark.c libtucmodel.a";b="test-conv-pool-cascade: tests/test_conv_pool_cascade.c libtucmodel.a";assert s.count(a)==s.count(b)==1;p.write_text(s.replace(a,"test-bench: tests/test_conv_pool_cascade.c libtucmodel.a").replace(b,"test-conv-pool-cascade: tests/test_benchmark.c libtucmodel.a"))' "$rel/Makefile";mh=$(sha256sum "$rel/Makefile"|cut -d' ' -f1);cp experiments/ch21_source_audit.py "$WORK_PARENT/rel-audit.py";python3 -c 'from pathlib import Path;import sys;p=Path(sys.argv[1]);s=p.read_text();old=sys.argv[2];assert s.count(old)==1;p.write_text(s.replace(old,sys.argv[3]))' "$WORK_PARENT/rel-audit.py" 5249a0e077438a4e6f70c74936c185bb1c30105bb834b3f89ac6a78b32630fd2 "$mh";set +e;python3 "$WORK_PARENT/rel-audit.py" "$rel" "$PIN" >"$RUN_DIR/relation-mutation.log" 2>&1;rrc=$?;set -e;[[ $rrc -ne 0 ]];printf 'RELATION_MUTATION count_preserved=22 rejected=1\n'
 cp experiments/ch21_source_audit.py "$WORK_PARENT/role-audit.py";python3 -c 'from pathlib import Path;import sys;p=Path(sys.argv[1]);s=p.read_text();old="counts=={\"question\":35";assert s.count(old)==1;p.write_text(s.replace(old,"counts=={\"question\":34"))' "$WORK_PARENT/role-audit.py";set +e;python3 "$WORK_PARENT/role-audit.py" "$WORK" "$PIN" "$WORK_PARENT/role-mut-inventory.json" >"$RUN_DIR/report-role-mutation.log" 2>&1;rrc=$?;set -e;[[ $rrc -ne 0 ]];printf 'REPORT_ROLE_MUTATION rejected=1\n'
 python3 experiments/ch21_boundary_audit.py "$WORK" "$PIN" "$BOOK_ROOT"|tee "$RUN_DIR/boundary-audit.log";local bc="$WORK_PARENT/bookclaims";mkdir -p "$bc/notes";for f in chapter-21-source-and-claim-ledger.md chapter-21-predraft-audit-report.md chapter-21-limitation-register.md chapter-21-worked-decision-schema.json;do cp "$BOOK_ROOT/notes/$f" "$bc/notes/$f";done;printf '\nSUPPORTED_BRIDGE compiler lowers ONNX and executes through cmodel\n' >>"$bc/notes/chapter-21-source-and-claim-ledger.md";set +e;python3 experiments/ch21_boundary_audit.py "$WORK" "$PIN" "$bc" >"$RUN_DIR/boundary-mutation.log" 2>&1;brc=$?;set -e;[[ $brc -ne 0 ]];printf 'BOUNDARY_MUTATION rejected=1\n'
 make -C "$WORK" -j2 libtucmodel.a >"$RUN_DIR/build.log" 2>&1;ar t "$WORK/libtucmodel.a" >"$RUN_DIR/archive-members.log";[[ $(wc -l <"$RUN_DIR/archive-members.log") -eq 44 ]]
 for opt in O0 O2;do cc -"$opt" -g -Wall -Wextra -std=c11 -I"$WORK" -I"$WORK/tu_cmodel" -o "$WORK_PARENT/probe-$opt" experiments/ch21_sweep_probe.c "$WORK/libtucmodel.a" -lm;readelf -d "$WORK_PARENT/probe-$opt" >"$RUN_DIR/probe-$opt-dynamic.log";! grep -Eq 'NEEDED.*libtucmodel' "$RUN_DIR/probe-$opt-dynamic.log";"$WORK_PARENT/probe-$opt" >"$RUN_DIR/probe-$opt.log" 2>"$RUN_DIR/probe-$opt.stderr.log";done;cmp -s "$RUN_DIR/probe-O0.log" "$RUN_DIR/probe-O2.log";printf 'PROBE_OPT_STABILITY byte_identical=1\n'
 cp experiments/ch21_sweep_probe.c "$WORK_PARENT/route-mut.c";python3 -c 'from pathlib import Path;import sys;p=Path(sys.argv[1]);s=p.read_text();old="core->state.dataflow=tu_dataflow_lookup(TU_DATAFLOW_OUTPUT_STATIONARY)";assert s.count(old)==1;p.write_text(s.replace(old,"core->state.dataflow=tu_dataflow_lookup(TU_DATAFLOW_WEIGHT_STATIONARY)"))' "$WORK_PARENT/route-mut.c";cc -O0 -std=c11 -I"$WORK" -I"$WORK/tu_cmodel" -o "$WORK_PARENT/route-mut" "$WORK_PARENT/route-mut.c" "$WORK/libtucmodel.a" -lm;set +e;"$WORK_PARENT/route-mut" >"$RUN_DIR/probe-route-mutation.log" 2>&1;prc=$?;set -e;[[ $prc -ne 0 ]];grep -F 'FAIL route-cycles' "$RUN_DIR/probe-route-mutation.log";printf 'ROUTE_MUTATION effective_selection_rejected=1\n'
 python3 "$WORK/scripts/sweep_aspect_ratio.py" >"$RUN_DIR/aspect-raw.log";grep -Fx '**Configs tested:** 120' "$RUN_DIR/aspect-raw.log";[[ $(grep -Ec '^\| [0-9]+ \| [0-9]+ \| [0-9]+ \|' "$RUN_DIR/aspect-raw.log") -eq 120 ]]
 python3 experiments/ch21_formula_probe.py "$WORK_PARENT/formula"|tee "$RUN_DIR/formula.log";cp "$WORK_PARENT/formula/"* "$RUN_DIR/"
 cp experiments/ch21_formula_probe.py "$WORK_PARENT/formula-mut.py";python3 -c 'from pathlib import Path;import sys;p=Path(sys.argv[1]);s=p.read_text();old="dma=math.ceil((M*K+K*N+M*N)*2/bus)";assert s.count(old)==2;p.write_text(s.replace(old,old+"+1",1))' "$WORK_PARENT/formula-mut.py";set +e;python3 "$WORK_PARENT/formula-mut.py" "$WORK_PARENT/fmut" >"$RUN_DIR/formula-mutation.log" 2>&1;frc=$?;set -e;[[ $frc -ne 0 ]];printf 'FORMULA_MUTATION stale_axis_rejected=1\n'
 cp "$WORK/scripts/sweep_aspect_ratio.py" "$WORK_PARENT/status-mut.py";python3 -c 'from pathlib import Path;import sys;p=Path(sys.argv[1]);s=p.read_text();old="total_cycles = fill + compute + drain + dma";assert s.count(old)>=1;p.write_text(s.replace(old,old+" + 1",1))' "$WORK_PARENT/status-mut.py";set +e;python3 "$WORK_PARENT/status-mut.py" >"$WORK_PARENT/status-mut.out" 2>"$RUN_DIR/status-mutation.log";src=$?;set -e;[[ $src -eq 0 ]];if cmp -s "$WORK_PARENT/status-mut.out" "$RUN_DIR/aspect-raw.log";then exit 1;fi;printf 'upstream_rc=0 output_mismatch=1 outer_rejected=1\n' >>"$RUN_DIR/status-mutation.log";printf 'STATUS_MUTATION upstream_zero_mismatch_rejected=1\n'
 python3 -c 'import json,sys;d=json.load(open(sys.argv[1]));assert len(d["worked_cases"])==4 and all(set(d["required_fields"])<=set(x) for x in d["worked_cases"]);print("DECISION_SCHEMA cases=4 required_fields=%d"%len(d["required_fields"]))' notes/chapter-21-worked-decision-schema.json|tee "$RUN_DIR/decision-schema-check.log";cp notes/chapter-21-metric-fidelity-register.json "$RUN_DIR/metric-register.json"
 source_state after_body;[[ $(git rev-parse HEAD) == "$INPUT_COMMIT" && $(git branch --show-current) == main ]];for rel in "${INPUTS[@]}";do cmp -s "$BOOK_ROOT/$rel" "$RUN_DIR/inputs/$rel";done;unexpected=$(git status --porcelain=v1|grep -v "^?? experiments/runs/$RUN_ID/"||true);[[ -z $unexpected ]];printf 'BOOK_INPUTS unchanged=1 head=%s\n' "$INPUT_COMMIT"
}
set +e;(set -euo pipefail;body) >"$TRANSCRIPT" 2>&1;body_rc=$?;set -e;tee /dev/null <"$TRANSCRIPT";[[ $body_rc -eq 0 ]]
CH21_RUN_ID="$RUN_ID" python3 experiments/ch21_predraft_validate.py --body >"$RUN_DIR/body-validation-normal.log";CH21_RUN_ID="$RUN_ID" python3 -O experiments/ch21_predraft_validate.py --body >"$RUN_DIR/body-validation-optimized.log";cmp -s "$RUN_DIR/body-validation-normal.log" "$RUN_DIR/body-validation-optimized.log"
cp "$RUN_DIR/inputs/notes/chapter-21-source-and-claim-ledger.md" "$WORK_PARENT/ledger";printf '\nMUTATION\n' >>"$RUN_DIR/inputs/notes/chapter-21-source-and-claim-ledger.md";for mode in normal optimized;do set +e;if [[ $mode == normal ]];then CH21_RUN_ID="$RUN_ID" python3 experiments/ch21_predraft_validate.py --body >"$RUN_DIR/validator-input-mutation-$mode.log" 2>&1;else CH21_RUN_ID="$RUN_ID" python3 -O experiments/ch21_predraft_validate.py --body >"$RUN_DIR/validator-input-mutation-$mode.log" 2>&1;fi;vrc=$?;set -e;[[ $vrc -ne 0 ]];source_state after >>"$RUN_DIR/validator-input-mutation-$mode.log";done;cp "$WORK_PARENT/ledger" "$RUN_DIR/inputs/notes/chapter-21-source-and-claim-ledger.md"
cp experiments/ch21_predraft_validate.py "$WORK_PARENT/validator-mut.py";printf '\nassert(False)\n' >>"$WORK_PARENT/validator-mut.py";for mode in normal optimized;do set +e;if [[ $mode == normal ]];then CH21_RUN_ID="$RUN_ID" python3 "$WORK_PARENT/validator-mut.py" --body >"$RUN_DIR/validator-assert-mutation-$mode.log" 2>&1;else CH21_RUN_ID="$RUN_ID" python3 -O "$WORK_PARENT/validator-mut.py" --body >"$RUN_DIR/validator-assert-mutation-$mode.log" 2>&1;fi;vrc=$?;set -e;[[ $vrc -ne 0 ]];grep -F 'validator-contains-assert' "$RUN_DIR/validator-assert-mutation-$mode.log";source_state after >>"$RUN_DIR/validator-assert-mutation-$mode.log";done
# Real manifest hierarchy controls under both interpreters: digest, missing, extra, duplicate, traversal, and symlink.
: >"$RUN_DIR/manifest-hierarchy-mutations.log";for mode in normal optimized;do passed=0;for case in digest missing extra duplicate traversal symlink;do f="$WORK_PARENT/mf-$mode-$case";mkdir -p "$f";printf a >"$f/a";printf b >"$f/b";(cd "$f"&&sha256sum a b >manifest);case $case in digest) printf '%064d  a\n' 0 >"$f/manifest";;missing) rm "$f/b";;extra) printf x >"$f/x";;duplicate) cat "$f/manifest" >>"$f/manifest";;traversal) printf '%064d  ../x\n' 0 >>"$f/manifest";;symlink) rm "$f/b";ln -s /etc/hosts "$f/b";;esac;set +e;if [[ $mode == normal ]];then python3 experiments/ch21_predraft_validate.py --manifest-fixture "$f" manifest a,b >>"$RUN_DIR/manifest-hierarchy-mutations.log" 2>&1;else python3 -O experiments/ch21_predraft_validate.py --manifest-fixture "$f" manifest a,b >>"$RUN_DIR/manifest-hierarchy-mutations.log" 2>&1;fi;mrc=$?;set -e;[[ $mrc -ne 0 ]];passed=$((passed+1));done;printf '%s_cases=%d\n' "$mode" "$passed" >>"$RUN_DIR/manifest-hierarchy-mutations.log";done;printf 'normal_cases=6 optimized_cases=6 all_rejected=1\n' >>"$RUN_DIR/manifest-hierarchy-mutations.log"
{ for rel in "${INPUTS[@]}";do printf 'inputs/%s\n' "$rel";done;printf '%s\n' "${BASE[@]}";}|LC_ALL=C sort >"$RUN_DIR/retained-files.txt"
(cd "$RUN_DIR";while read -r rel;do sha256sum "$rel";done <retained-files.txt;sha256sum retained-files.txt)>"$RUN_DIR/sha256-retained.txt";(cd "$RUN_DIR"&&sha256sum -c sha256-retained.txt)>"$RUN_DIR/manifest-check.log"
printf 'FINALIZED_RUN run=%s transcript_sha256=%s input_commit=%s trust=exact-payload,root-manifest,derived-receipts,git-seal authorization=post-review-evidence-authorized\n' "$RUN_ID" "$(sha256sum "$TRANSCRIPT"|cut -d' ' -f1)" "$INPUT_COMMIT" >"$RUN_DIR/finalization.log"
CH21_RUN_ID="$RUN_ID" python3 experiments/ch21_predraft_validate.py >"$RUN_DIR/predraft-validation-normal.log";CH21_RUN_ID="$RUN_ID" python3 -O experiments/ch21_predraft_validate.py >"$RUN_DIR/predraft-validation-optimized.log";cmp -s "$RUN_DIR/predraft-validation-normal.log" "$RUN_DIR/predraft-validation-optimized.log"
(cd "$RUN_DIR";sha256sum sha256-retained.txt manifest-check.log finalization.log predraft-validation-normal.log predraft-validation-optimized.log >bundle-sha256.txt;sha256sum -c bundle-sha256.txt >bundle-check.log)
: >"$RUN_DIR/closure-validation-normal.log";: >"$RUN_DIR/closure-validation-optimized.log";CH21_RUN_ID="$RUN_ID" python3 experiments/ch21_predraft_validate.py --outer >"$RUN_DIR/closure-validation-normal.log";CH21_RUN_ID="$RUN_ID" python3 -O experiments/ch21_predraft_validate.py --outer >"$RUN_DIR/closure-validation-optimized.log";cmp -s "$RUN_DIR/closure-validation-normal.log" "$RUN_DIR/closure-validation-optimized.log"
source_state after_closure;AFTER_DONE=1;trap - EXIT;rm -rf "$WORK_PARENT"
